def _hex_to_bytes(hex_str: str) -> bytes:
    parts = hex_str.replace("\n", " ").split()
    return bytes(int(p, 16) for p in parts)


def _bytes_to_int16_list(data: bytes) -> List[int]:
    if len(data) % 2:
        raise ValueError("int16 data size must be even")
    count = len(data) // 2
    return list(struct.unpack("<" + "h" * count, data))


def _bytes_to_int32_list(data: bytes) -> List[int]:
    if len(data) % 4:
        raise ValueError("int32 data size must be multiple of 4")
    count = len(data) // 4
    return list(struct.unpack("<" + "i" * count, data))


def _to_int16(value: int) -> int:
    value &= 0xFFFF
    return value - 0x10000 if value & 0x8000 else value


def _to_uint16(value: int) -> int:
    return value & 0xFFFF


def _convolve_circular(coeffs: List[int], delay: List[int], idx: int) -> int:
    acc = 0
    size = len(coeffs)
    for i in range(size):
        acc += coeffs[i] * delay[(idx - i) % size]
    return acc


