@dataclass
class RcFixedContextMode0:
    coeffs: List[int]
    window_buf: List[int]
    remainder: int
    down_factor: int
    up_factor: int
    window_len: int
    index_copy: int
    pending_count: int


@dataclass
class RcFixedContextMode1:
    rate_divider: int
    b1_history: List[int]
    droop_coeffs: List[int]
    b1_history_idx: int
    b1_delay: List[int]
    b1_coeffs: List[int]
    b1_idx: int
    b2_delay: List[int]
    b2_coeffs: List[int]
    b2_idx: int


@dataclass
class RcFixedHandle:
    mode: int
    ctx: Optional[object]


def RcFixed_Create(ratio_code: RcRatioCode) -> Optional[RcFixedHandle]:
    if int(ratio_code) > RcRatioCode.RC_8K_TO_7_2K:
        return None

    if ratio_code <= RcRatioCode.RC_CASCADE_DOWNSAMPLE_4:
        ctx1 = RcFixedContextMode1(
            rate_divider=int(ratio_code),
            b1_history=[0] * 3,
            droop_coeffs=CI_bDroop,
            b1_history_idx=0,
            b1_delay=[0] * 87,
            b1_coeffs=CI_b1,
            b1_idx=0,
            b2_delay=[0] * 15,
            b2_coeffs=CI_b2,
            b2_idx=0,
        )
        return RcFixedHandle(mode=1, ctx=ctx1)

    if ratio_code <= RcRatioCode.RC_8K_TO_7_2K:
        up_factor = int(fixedRc_UpFact[int(ratio_code)])
        down_factor = int(fixedRc_DownFact[int(ratio_code)])

        coeffs = rc80to96filter
        window_len = 0

        if ratio_code in (RcRatioCode.RC_8K_TO_9_6K, RcRatioCode.RC_8K_TO_48K):
            coeffs = rc80to96filter
            window_len = 36
        elif ratio_code in (RcRatioCode.RC_9_6K_TO_8K, RcRatioCode.RC_9_6K_TO_48K):
            coeffs = rc96to80filter
            window_len = 32
        elif ratio_code == RcRatioCode.RC_48K_TO_8K:
            coeffs = rc480to80filter
            window_len = 68
        elif ratio_code == RcRatioCode.RC_48K_TO_9_6K:
            coeffs = rc480to96filter
            window_len = 68
        elif ratio_code == RcRatioCode.RC_9_6K_TO_38_4K:
            coeffs = rc96to384filter
            window_len = 46
        elif ratio_code == RcRatioCode.RC_38_4K_TO_9_6K:
            coeffs = rc384to96filter
            window_len = 68
        elif ratio_code == RcRatioCode.RC_8K_TO_38_4K:
            coeffs = rc80to384filter
            window_len = 40
        elif ratio_code == RcRatioCode.RC_38_4K_TO_8K:
            coeffs = rc384to80filter
            window_len = 68
        elif ratio_code == RcRatioCode.RC_9_6K_TO_12K:
            coeffs = rc96to120filter
            window_len = 28
        elif ratio_code == RcRatioCode.RC_12K_TO_9_6K:
            coeffs = rc120to96filter
            window_len = 58
        elif ratio_code == RcRatioCode.RC_8K_TO_12K:
            coeffs = rc80to120filter
            window_len = 42
        elif ratio_code == RcRatioCode.RC_12K_TO_8K:
            coeffs = rc120to80filter
            window_len = 48
        elif ratio_code == RcRatioCode.RC_9_6K_TO_32K:
            coeffs = rc96to320filter
            window_len = 38
        elif ratio_code == RcRatioCode.RC_32K_TO_9_6K:
            coeffs = rc320to96filter
            window_len = 68
        elif ratio_code == RcRatioCode.RC_7_2K_TO_8K:
            coeffs = rc72to80filter
            window_len = 38
        elif ratio_code == RcRatioCode.RC_8K_TO_7_2K:
            coeffs = rc80to72filter
            window_len = 32

        remainder = down_factor % up_factor
        if remainder & 0x8000:
            remainder = remainder + up_factor

        ctx0 = RcFixedContextMode0(
            coeffs=coeffs,
            window_buf=[0] * 200,
            remainder=remainder,
            down_factor=down_factor,
            up_factor=up_factor,
            window_len=window_len,
            index_copy=window_len,
            pending_count=1 if up_factor <= down_factor else 0,
        )
        return RcFixedHandle(mode=0, ctx=ctx0)

    return None


def RcFixed_Delete(handle: Optional[RcFixedHandle]) -> None:
    return None


def RcFixed_Reset(handle: RcFixedHandle) -> int:
    if handle.mode == 1:
        ctx1 = handle.ctx
        if not isinstance(ctx1, RcFixedContextMode1):
            return 0
        ctx1.b1_history = [0] * 3
        ctx1.b1_delay = [0] * 87
        ctx1.b2_delay = [0] * 15
        ctx1.b1_history_idx = 0
        ctx1.b1_idx = 0
        ctx1.b2_idx = 0
        return 0

    ctx0 = handle.ctx
    if not isinstance(ctx0, RcFixedContextMode0):
        return 0
    ctx0.window_buf = [0] * 200
    ctx0.index_copy = ctx0.window_len
    ctx0.pending_count = 1 if ctx0.up_factor <= ctx0.down_factor else 0
    remainder = ctx0.down_factor % ctx0.up_factor
    if remainder & 0x8000:
        remainder = remainder + ctx0.up_factor
    ctx0.remainder = remainder
    return ctx0.down_factor // ctx0.up_factor


def RcFixed_Resample(
    handle: RcFixedHandle,
    in_samples: List[int],
    out_capacity: int,
) -> Tuple[List[int], int]:
    if handle.mode == 1:
        ctx = handle.ctx
        if not isinstance(ctx, RcFixedContextMode1):
            return [], 0

        out_samples = [0] * out_capacity
        out_count = 0

        if ctx.rate_divider == 1:
            var34 = 0
            v186 = 0
            for sample in in_samples:
                ctx.b2_idx = (ctx.b2_idx + 1) % 15
                ctx.b2_delay[ctx.b2_idx] = _to_int16(sample >> 1)
                acc_b2 = _convolve_circular(ctx.b2_coeffs, ctx.b2_delay, ctx.b2_idx)
                acc_b1 = acc_b2 >> 15
                var34 += 1
                if var34 == 2:
                    var34 = 0
                    ctx.b1_idx = (ctx.b1_idx + 1) % 87
                    ctx.b1_delay[ctx.b1_idx] = _to_int16(acc_b1)
                    acc_b1_coeffs = _convolve_circular(
                        ctx.b1_coeffs, ctx.b1_delay, ctx.b1_idx
                    )
                    v152 = acc_b1_coeffs >> 15
                    v186 += 1
                    if v186 == 2:
                        v186 = 0
                        ctx.b1_history_idx = (ctx.b1_history_idx + 1) % 3
                        ctx.b1_history[ctx.b1_history_idx] = _to_int16(v152)
                        acc_droop_sum = _convolve_circular(
                            ctx.droop_coeffs, ctx.b1_history, ctx.b1_history_idx
                        )
                        out_samples[out_count] = _to_int16(
                            (32440 * (acc_droop_sum >> 15)) >> 13
                        )
                        out_count += 1
                        if out_count >= out_capacity:
                            break
        else:
            v187 = 0
            for sample in in_samples:
                ctx.b1_history_idx = (ctx.b1_history_idx + 1) % 3
                ctx.b1_history[ctx.b1_history_idx] = _to_int16(sample)
                acc_droop = _convolve_circular(
                    ctx.droop_coeffs, ctx.b1_history, ctx.b1_history_idx
                )

                ctx.b1_idx = (ctx.b1_idx + 1) % 87
                ctx.b1_delay[ctx.b1_idx] = _to_int16(acc_droop >> 15)
                v65 = _convolve_circular(ctx.b1_coeffs, ctx.b1_delay, ctx.b1_idx)
                v171 = ((v65 >> 14) & 0xFFFE) | (v187 & 0xFFFF0000)

                ctx.b1_idx = (ctx.b1_idx + 1) % 87
                ctx.b1_delay[ctx.b1_idx] = 0
                v73 = _convolve_circular(ctx.b1_coeffs, ctx.b1_delay, ctx.b1_idx)
                v187 = ((4 * v73) & 0xFFFE0000) | (v171 & 0xFFFF)
                v187 &= 0xFFFFFFFF

                ctx.b2_idx = (ctx.b2_idx + 1) % 15
                ctx.b2_delay[ctx.b2_idx] = _to_int16(v187)
                v86 = _convolve_circular(ctx.b2_coeffs, ctx.b2_delay, ctx.b2_idx)
                out_samples[out_count] = _to_int16((31957 * (v86 >> 15)) >> 13)

                ctx.b2_idx = (ctx.b2_idx + 1) % 15
                ctx.b2_delay[ctx.b2_idx] = 0
                v99 = _convolve_circular(ctx.b2_coeffs, ctx.b2_delay, ctx.b2_idx)
                if out_count + 1 < out_capacity:
                    out_samples[out_count + 1] = _to_int16(
                        (31957 * (v99 >> 15)) >> 13
                    )

                ctx.b2_idx = (ctx.b2_idx + 1) % 15
                ctx.b2_delay[ctx.b2_idx] = _to_int16((v187 >> 16) & 0xFFFF)
                v112 = _convolve_circular(ctx.b2_coeffs, ctx.b2_delay, ctx.b2_idx)
                if out_count + 2 < out_capacity:
                    out_samples[out_count + 2] = _to_int16(
                        (31957 * (v112 >> 15)) >> 13
                    )

                ctx.b2_idx = (ctx.b2_idx + 1) % 15
                ctx.b2_delay[ctx.b2_idx] = 0
                v127 = _convolve_circular(ctx.b2_coeffs, ctx.b2_delay, ctx.b2_idx)
                if out_count + 3 < out_capacity:
                    out_samples[out_count + 3] = _to_int16(
                        (31957 * (v127 >> 15)) >> 13
                    )

                out_count += 4
                if out_count >= out_capacity:
                    break

        return out_samples[:out_count], out_count

    if handle.mode == 0:
        ctx0 = handle.ctx
        if not isinstance(ctx0, RcFixedContextMode0):
            return [], 0

        out_samples = [0] * out_capacity
        out_count = 0
        in_index = 0
        remaining = len(in_samples)

        while remaining:
            pending = ctx0.pending_count
            count = min(pending, remaining)
            if count:
                index_copy = ctx0.index_copy
                for _ in range(count):
                    sample_in = _to_int16(in_samples[in_index])
                    in_index += 1
                    next_index_copy = index_copy + 1
                    index_wrap = index_copy == 199
                    ctx0.window_buf[index_copy] = sample_in
                    index_copy = next_index_copy
                    if index_wrap:
                        index_copy = ctx0.window_len
                        start = next_index_copy - index_copy
                        if ctx0.window_len:
                            for i in range(ctx0.window_len):
                                ctx0.window_buf[i] = ctx0.window_buf[start + i]
                ctx0.index_copy = index_copy

            if pending > remaining:
                ctx0.pending_count = pending - remaining
                break

            remaining -= pending
            base = ctx0.window_len * ctx0.remainder
            acc = 0
            start = ctx0.index_copy - ctx0.window_len
            for i in range(ctx0.window_len):
                acc += ctx0.coeffs[base + i] * ctx0.window_buf[start + i]
            out_samples[out_count] = _to_int16(acc >> 14)
            out_count += 1

            remainder = ctx0.remainder
            down_factor = ctx0.down_factor
            ctx0.pending_count = 0
            v25 = remainder + down_factor
            up_factor = ctx0.up_factor
            ctx0.remainder = v25
            if up_factor <= v25:
                pending_count = 0
                while v25 >= up_factor:
                    pending_count += 1
                    v25 -= up_factor
                ctx0.remainder = v25
                ctx0.pending_count = pending_count

            if out_count == out_capacity:
                break

        return out_samples[:out_count], out_count

    return [], 0
